interface.definition:
a!localVariables(
  local!hexOrange: "#FFDFBF",
  local!hexGreen: "#D3F8D3",
  #"SYSTEM_SYSRULES_columnsLayout"(
    columns: {
      #"SYSTEM_SYSRULES_columnLayout"(width: "NARROW"),
      /*Rotational Ask Columns*/
      #"SYSTEM_SYSRULES_columnLayout"(
        contents: #"SYSTEM_SYSRULES_cardLayout"(
          contents: #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                  value: {
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "Plan", 
                      style: "STRONG"
                    )
                  },
                  align: "CENTER"
                ),
                width: "EXTRA_NARROW"
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "Traditional Rotational", 
                        style: "STRONG"
                      )
                    },
                    preventWrapping: true,
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_columnsLayout"(
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: if(
                                #"SYSTEM_SYSRULES_isPageWidth"("DESKTOP_NARROW"),
                                "Conf.",
                                "Confirmed"
                              ),
                              style: "STRONG"
                            ),
                            preventWrapping: true,
                            align: "CENTER"
                          )
                        }
                      ),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "In Process",
                              style: "STRONG"
                            ),
                            preventWrapping: true,
                            align: "CENTER"
                          )
                        }
                      )
                    },
                    spacing: "NONE"
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    value: {
                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                        text: "Early Career Rotational", 
                        style: "STRONG"
                      )
                    },
                    preventWrapping: true,
                    align: "CENTER"
                  ),
                  #"SYSTEM_SYSRULES_columnsLayout"(
                    columns: {
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: if(
                                #"SYSTEM_SYSRULES_isPageWidth"("DESKTOP_NARROW"),
                                "Conf.",
                                "Confirmed"
                              ),
                              style: "STRONG"
                            ),
                            preventWrapping: true,
                            align: "CENTER"
                          )
                        }
                      ),
                      #"SYSTEM_SYSRULES_columnLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_richTextDisplayField"(
                            labelPosition: "COLLAPSED",
                            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: "In Process",
                              style: "STRONG"
                            ),
                            preventWrapping: true,
                            align: "CENTER"
                          )
                        }
                      )
                    },
                    spacing: "NONE"
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
                  value: {
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "Var.", 
                      style: "STRONG"
                    )
                  },
                  align: "CENTER"
                ),
                width: "EXTRA_NARROW"
              )
            },
            alignVertical: "BOTTOM",
            showDividers: true
          ),
          style: local!hexOrange
        ),
        width: if(
          #"SYSTEM_SYSRULES_isPageWidth"({"DESKTOP_NARROW","DESKTOP"}),
          "MEDIUM",
          "WIDE"
        ),
        showWhen: or(a!isNullOrEmpty(ri!typeFilter),ri!typeFilter="Rotational")
      ),
      /* Non-traditional & Other Rotationals*/
      #"SYSTEM_SYSRULES_columnLayout"(
        contents: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6619708"(
          color: local!hexGreen,
          title: "Non-Traditional/Other Rotational"
        ),
        width: "NARROW",
        showWhen: or(a!isNullOrEmpty(ri!typeFilter),ri!typeFilter="Rotational")
      ),
      #"SYSTEM_SYSRULES_columnLayout"(
        contents: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6619708"(
          color: local!hexGreen,
          title: "Transitional Core"
        ),
        width: "NARROW",
        showWhen: or(a!isNullOrEmpty(ri!typeFilter),ri!typeFilter="Core")
      ),
      #"SYSTEM_SYSRULES_columnLayout"(
        contents: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6619708"(
          color: local!hexGreen,
          title: "Core Partner/Professional"
        ),
        width: "NARROW",
        showWhen: or(a!isNullOrEmpty(ri!typeFilter),ri!typeFilter="Core")
      ),
      #"SYSTEM_SYSRULES_columnLayout"(
        contents: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6619708"(
          color: "INFO",
          title: "Total"
        ),
        width: "NARROW"
      )
    },
    alignVertical: "BOTTOM",
    marginBelow: "NONE",
    spacing: "NONE"
  )
)
